// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    uint constant TICKET_AMOUNT = 10;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 ts, uint256 difficulty) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.warp(ts);
        vm.roll(difficulty);
        uint256 random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        // exercise the losing branch (no payout): pot must equal tickets * price
        vm.assume(random == 1);

        vm.deal(actor, TICKET_AMOUNT);
        vm.prank(actor);
        c.play{value: TICKET_AMOUNT}();

        assertEq(c.pot(), TICKET_AMOUNT);
    }
}
